#include <EEPROM.h>
#include <LiquidCrystal_I2C.h>
#include <Wire.h>
#include <RDA5807.h>

RDA5807 rx;
LiquidCrystal_I2C lcd(0x27, 20, 4);

// Кастомные символы для крупных цифр
byte v1[8] = {0x07,0x07,0x07,0x07,0x07,0x07,0x07,0x07};
byte v2[8] = {0x07,0x07,0x00,0x00,0x00,0x00,0x00,0x00};
byte v3[8] = {0x00,0x00,0x00,0x00,0x00,0x00,0x1F,0x1F};
byte v4[8] = {0x1F,0x1F,0x00,0x00,0x00,0x00,0x1F,0x1F};
byte v5[8] = {0x1C,0x1C,0x00,0x00,0x00,0x00,0x1C,0x1C};
byte v6[8] = {0x1C,0x1C,0x1C,0x1C,0x1C,0x1C,0x1C,0x1C};
byte v7[8] = {0x00,0x00,0x00,0x00,0x00,0x00,0x07,0x07};
byte v8[8] = {0x1F,0x1F,0x00,0x00,0x00,0x00,0x00,0x00};

byte d1,d2,d3,d4,d5,d6,e1,e2,e3;
int a[6], x;
int vol;
uint16_t currentFreq;
unsigned long times, times1;
bool save_ch = false;
bool firstDraw = true;

// Отслеживание изменений (чтобы не мерцало)
int lastFreqVal = -1;
int lastVol = -1;
int lastRssi = -1;
bool lastStereo = false;
String lastRdsName = "";

// Пины кнопок
const int btnUp = 7;
const int btnDown = 8;
const int btnVolUp = 9;
const int btnVolDown = 10;

void setup() {
  Wire.begin();
  lcd.init();
  lcd.backlight();

  lcd.createChar(1, v1); lcd.createChar(2, v2); lcd.createChar(3, v3); lcd.createChar(4, v4);
  lcd.createChar(5, v5); lcd.createChar(6, v6); lcd.createChar(7, v7); lcd.createChar(8, v8);

  pinMode(btnUp, INPUT_PULLUP);
  pinMode(btnDown, INPUT_PULLUP);
  pinMode(btnVolUp, INPUT_PULLUP);
  pinMode(btnVolDown, INPUT_PULLUP);

  // Чтение из EEPROM
  currentFreq = ((EEPROM.read(400) << 8)) | EEPROM.read(401);
  vol = EEPROM.read(402);
  if (currentFreq < 8750 || currentFreq > 10800) currentFreq = 10190; // 101.9 МГц по умолчанию
  if (vol > 15) vol = 5;

  rx.setup();
  rx.setVolume(vol);
  rx.setFrequency(currentFreq);
  rx.setRDS(true);
  rx.setMono(false);
  rx.setMute(false);
}

void loop() {
  // Кнопки
  if (digitalRead(btnUp) == LOW) {
    rx.seek(RDA_SEEK_WRAP, RDA_SEEK_UP);
    save_ch = true; times = millis(); delay(200);
    lastRdsName = ""; // Сброс RDS при смене станции
  }
  if (digitalRead(btnDown) == LOW) {
    rx.seek(RDA_SEEK_WRAP, RDA_SEEK_DOWN);
    save_ch = true; times = millis(); delay(200);
    lastRdsName = "";
  }
  if (digitalRead(btnVolUp) == LOW) {
    vol++; if (vol > 15) vol = 15;
    rx.setVolume(vol);
    save_ch = true; times = millis(); delay(200);
  }
  if (digitalRead(btnVolDown) == LOW) {
    vol--; if (vol < 0) vol = 0;
    rx.setVolume(vol);
    save_ch = true; times = millis(); delay(200);
  }

  // Сохранение в EEPROM (через минуту после последнего нажатия)
  if (millis() - times > 60000 && save_ch) {
    save_ch = false;
    currentFreq = rx.getFrequency();
    EEPROM.update(400, (currentFreq >> 8) & 0xFF);
    EEPROM.update(401, currentFreq & 0xFF);
    EEPROM.update(402, vol);
  }

  currentFreq = rx.getFrequency();
  drawUI();
  delay(10);
}

void drawUI() {
  int rssi = rx.getRssi();
  bool stereo = rx.isStereo();
  // Частота: 10кГц → МГц×10 (10190 → 1019)
  int f_ch = currentFreq / 10;

  // === КРУПНЫЕ ЦИФРЫ (строки 0-1, колонки 0-11) ===
  if (f_ch != lastFreqVal || firstDraw) {
    lastFreqVal = f_ch;
    a[0] = f_ch / 1000;
    a[1] = (f_ch / 100) % 10;
    a[2] = (f_ch / 10) % 10;
    a[3] = f_ch % 10;
    if (f_ch < 1000) a[0] = 10; // пусто для частот < 100 МГц

    for (x = 0; x < 4; x++) {
      switch(x) {
        case 0: e1=0; e2=0; e3=1; break;
        case 1: e1=2; e2=3; e3=4; break;
        case 2: e1=5; e2=6; e3=7; break;
        case 3: e1=9; e2=10; e3=11; break;
      }
      digit();
    }
    lcd.setCursor(8, 1);
    lcd.print(".");
  }

  // === VOL (строка 0, колонка 13) ===
  if (vol != lastVol || firstDraw) {
    lastVol = vol;
    lcd.setCursor(13, 0);
    lcd.print("VOL ");
    lcd.print(vol);
    lcd.print(" ");
  }

  // === STEREO/MONO и SIG (раз в секунду) ===
  static unsigned long lastStatusUpdate = 0;
  if (millis() - lastStatusUpdate > 1000 || firstDraw) {
    lastStatusUpdate = millis();

    if (stereo != lastStereo || firstDraw) {
      lastStereo = stereo;
      lcd.setCursor(13, 1);
      if (stereo) lcd.print("STEREO");
      else lcd.print("MONO  ");
    }

    if (rssi != lastRssi || firstDraw) {
      lastRssi = rssi;
      lcd.setCursor(13, 2);
      lcd.print("SIG ");
      lcd.print(rssi);
      lcd.print(" ");
    }
  }

  // === FM RADIO (строка 2, колонка 2) — статично ===
  if (firstDraw) {
    lcd.setCursor(2, 2);
    lcd.print("FM RADIO");
  }

  // === RDS (строка 3) — раз в 500мс ===
  static unsigned long lastRdsUpdate = 0;
  if (millis() - lastRdsUpdate > 500 || firstDraw) {
    lastRdsUpdate = millis();

    String rdsName = " No RDS ";
    if (rx.hasRdsInfo()) {
      char* name = rx.getRdsText0A();
      if (name != NULL && strlen(name) > 0) {
        rdsName = "";
        for (int i = 0; i < 8; i++) {
          if (name[i] == 0) rdsName += " ";
          else rdsName += (char)name[i];
        }
      }
    }

    if (rdsName != lastRdsName || firstDraw) {
      lastRdsName = rdsName;
      lcd.setCursor(0, 3);
      lcd.print("======");
      lcd.setCursor(6, 3);
      lcd.print(rdsName);
      lcd.setCursor(14, 3);
      lcd.print("======");
    }
  }

  firstDraw = false;
}

void digit() {
  switch(a[x]) {
    case 0:  d1=1,  d2=8, d3=6, d4=1, d5=3, d6=6; break;
    case 1:  d1=32, d2=2, d3=6, d4=32, d5=32, d6=6; break;
    case 2:  d1=2,  d2=8, d3=6, d4=1, d5=4, d6=5; break;
    case 3:  d1=2,  d2=4, d3=6, d4=7, d5=3, d6=6; break;
    case 4:  d1=1,  d2=3, d3=6, d4=32, d5=32, d6=6; break;
    case 5:  d1=1,  d2=4, d3=5, d4=7, d5=3, d6=6; break;
    case 6:  d1=1,  d2=4, d3=5, d4=1, d5=3, d6=6; break;
    case 7:  d1=1,  d2=8, d3=6, d4=32, d5=32, d6=6; break;
    case 8:  d1=1,  d2=4, d3=6, d4=1, d5=3, d6=6; break;
    case 9:  d1=1,  d2=4, d3=6, d4=7, d5=3, d6=6; break;
    case 10: d1=32, d2=32, d3=32, d4=32, d5=32, d6=32; break; // пусто
  }
  if (x > 0) { lcd.setCursor(e1, 0); lcd.write((uint8_t)d1); }
  lcd.setCursor(e2, 0); lcd.write((uint8_t)d2);
  lcd.setCursor(e3, 0); lcd.write((uint8_t)d3);
  lcd.setCursor(e1, 1); lcd.write((uint8_t)d4);
  lcd.setCursor(e2, 1); lcd.write((uint8_t)d5);
  lcd.setCursor(e3, 1); lcd.write((uint8_t)d6);
}
